select * from ai_document_chunk
where kb_id = #{kbId}

    and embedding_status = #{embeddingStatus}

order by created_at desc

select * from ai_document_chunk
where document_id = #{documentId}

    and embedding_status = #{embeddingStatus}

order by chunk_index asc

mapper.update:
update ai_document_chunk
set embedding_status = #{embeddingStatus}, updated_at = now()
where document_id = #{documentId}

mapper.select:
select * from ai_document_chunk
where kb_id = #{kbId} and content_hash = #{contentHash}
limit 1
